    public Long getId() {
        return user.id();
    }

    public RoleDto getRole() {
        return user.role();
    }

    @Override
    public Collection<? extends GrantedAuthority> getAuthorities() {
        return List.of(new SimpleGrantedAuthority(ROLE_PREFIX + user.role().name()));
